-- | Frozen external-codec behavior from the pre-port implementation. The oracle
-- includes malformed input and exact generated bytes, not candidate round trips.
-- ref:DEC-haskell-application-port ref:REQ-compiler-api-contract
module ManifestCodecSpec (spec) where

import Control.Monad (forM_)
import Data.Aeson
import Data.Aeson.Types (parseEither)
import qualified Data.ByteString.Lazy as B
import LawSpec.Manifest.EDN
import Test.Hspec

data Fixture = Fixture String String (Either String (String, String, String))

instance FromJSON Fixture where
  parseJSON = withObject "manifest fixture" $ \fields -> do
    name <- fields .: "name"
    input <- fields .: "input"
    problem <- fields .:? "error"
    result <- case problem of
      Just message -> pure (Left message)
      Nothing -> Right <$> ((,,) <$> fields .: "json" <*> fields .: "readable" <*> fields .: "compact")
    pure (Fixture name input result)

-- | Compare independent recorded outputs, including malformed-input failures.
spec :: Spec
spec = describe "manifest EDN reference compatibility" $ do
  fixtures <- runIO $ do
    bytes <- B.readFile "test/fixtures/application-port/manifest-codec.json"
    either fail pure (eitherDecode bytes >>= parseEither (withObject "reference" (.: "cases")) :: Either String [Fixture])
  forM_ fixtures $ \(Fixture name input expected) ->
    it name $ case expected of
      Left problem -> parseManifest input `shouldBe` Left (ManifestError problem)
      Right (value, readable, compact) -> case parseManifest input of
        Left problem -> expectationFailure (show problem)
        Right result -> do
          encodeManifestJSON result `shouldBe` value
          writeManifest False result `shouldBe` readable
          writeManifest True result `shouldBe` compact
